/** Statuses that count as closed for stats, digests and overdue checks. */
export const CLOSED_ISSUE_STATUSES: readonly IssueStatus[] = ["done", "canceled"];

/** Group names the status filter accepts alongside the statuses (ADR 0009). */
export const ISSUE_STATUS_GROUPS = ["open", "closed"] as const;
export type IssueStatusGroup = (typeof ISSUE_STATUS_GROUPS)[number];

/** What the `open` group stands for: every status that is not closed. */
export const OPEN_ISSUE_STATUSES: readonly IssueStatus[] = ISSUE_STATUSES.filter(
  (status) => !CLOSED_ISSUE_STATUSES.includes(status),
);

/**
 * Expands status filter values into the statuses they name, each once, in the
 * order they first appear. Unknown values are not handled here: the URL codec
 * drops them and the schema refuses them.
 */
export function expandIssueStatuses(
  values: readonly (IssueStatus | IssueStatusGroup)[],
): IssueStatus[] {
  const expanded: IssueStatus[] = [];
  for (const value of values) {
    const members =
      value === "open"
        ? OPEN_ISSUE_STATUSES
        : value === "closed"
          ? CLOSED_ISSUE_STATUSES
          : [value];
    for (const status of members) {
      if (!expanded.includes(status)) expanded.push(status);
    }
  }
  return expanded;
}

