/** A status filter value: one status, or the `open` / `closed` group (ADR 0009). */
export const issueStatusFilterSchema = z.union([
  issueStatusSchema,
  z.enum(ISSUE_STATUS_GROUPS),
]);

/** `assignee`: a user id, `me`, or unassigned — `null`, or `none` as the URL spells it. */
export const assigneeFilterSchema = z.union([
  userIdSchema,
  z.literal(ME_FILTER_TOKEN),
  z.union([z.null(), z.literal("none")]).transform(() => null),
]);

/** `author`: a user id, or `me`. */
export const authorFilterSchema = z.union([
  userIdSchema,
  z.literal(ME_FILTER_TOKEN),
]);

/**
 * `due_before`: a calendar day, which includes that whole UTC day, or a full
 * ISO-8601 timestamp, which matches only issues due strictly before it.
 */
export const dueBeforeSchema = z.union([
  z
    .string()
    .refine(isCalendarDate, "must be a YYYY-MM-DD date")
    .transform((value) => value as CalendarDate),
  z
    .iso.datetime({ offset: true })
    .transform((value) => toIsoTimestamp(value)),
]);

/**
 * The filter vocabulary every entry point shares (ADR 0009). The URL codec
 * produces these keys, and the issue list, the export and the API validate them.
 */
export const issueFilterFieldsSchema = z.object({
  projectId: projectIdSchema.optional(),
  status: z.array(issueStatusFilterSchema).optional(),
  priority: z.array(issuePrioritySchema).optional(),
  assigneeId: assigneeFilterSchema.optional(),
  authorId: authorFilterSchema.optional(),
  labelIds: z.array(labelIdSchema).optional(),
  query: z.string().max(200).optional(),
  dueBefore: dueBeforeSchema.optional(),
  includeArchived: z.boolean().optional(),
  archivedOnly: z.boolean().optional(),
});

export const issueFilterSchema = z
  .object({ orgId: orgIdSchema })
  .extend(issueFilterFieldsSchema.shape)
  .extend(pageRequestSchema.shape);

