import { activeFilterCount, UNASSIGNED_TOKEN } from "@/hooks/issue-filter-params";
import {
  CLOSED_ISSUE_STATUSES,
  ISSUE_STATUSES,
  ME_FILTER_TOKEN,
  OPEN_ISSUE_STATUSES,
  type IssueFilter,
  type IssueStatus,
} from "@/types/issue";
import type { UserId } from "@/types/common";
import type { MemberWithUser } from "@/types/member";
import type { Project } from "@/types/project";
import type { ProjectId } from "@/types/common";
import type { ReactElement } from "react";

export type IssueFilterBarProps = {
  filter: IssueFilter;
  projects: readonly Project[];
  members: readonly MemberWithUser[];
  onChange: (filter: IssueFilter) => void;
};

/** One status chip: a single status, or a group that stands for several. */
type StatusChip = {
  key: string;
  label: string;
  statuses: readonly IssueStatus[];
};

const STATUS_CHIPS: readonly StatusChip[] = [
  { key: "open", label: "Open", statuses: OPEN_ISSUE_STATUSES },
  { key: "closed", label: "Closed", statuses: CLOSED_ISSUE_STATUSES },
  ...ISSUE_STATUSES.map((status) => ({
    key: status,
    label: status.replace(/_/g, " "),
    statuses: [status],
  })),
];

/**
 * Adds the statuses when any of them is missing, and removes them when all are
 * present, without disturbing the other dimensions.
 */
export function toggleStatuses(
  filter: IssueFilter,
  statuses: readonly IssueStatus[],
): IssueFilter {
  const current = filter.status ?? [];
  const allPresent = statuses.every((status) => current.includes(status));
  const wanted = allPresent
    ? current.filter((status) => !statuses.includes(status))
    : [...current, ...statuses];
  const next = ISSUE_STATUSES.filter((status) => wanted.includes(status));
  const { status: _dropped, ...rest } = filter;
  return next.length === 0 ? rest : { ...rest, status: next };
}

/** Adds or removes one status without disturbing the other dimensions. */
export function toggleStatus(
  filter: IssueFilter,
  status: IssueStatus,
): IssueFilter {
  return toggleStatuses(filter, [status]);
}

