import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("./server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("./server/_support/doubles/misc")).loggerModule);

import { parseIssueFilterParams, issueFilterToParams } from "@/hooks/issue-filter-params";
import { issueFilterSchema, exportIssuesSchema } from "@/schemas/index";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import * as issueService from "@/server/services/issue-service";
import { orgPath, withSearchParams } from "@/lib/url";
import { toIsoTimestamp, type CalendarDate } from "@/types/common";
import { createTenant, issueInput, useTemporaryDatabase } from "./server/_support/fixtures";
import type { Tenant } from "./server/_support/fixtures";

let cleanup: () => void;
let t: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  t = await createTenant("scratchfilters");
});

afterAll(() => cleanup());

async function insert(
  overrides: Partial<{ title: string; assigneeId: any; dueAt: string | null; status: any; description: string | null }> = {},
  labelIds: any[] = [],
  author = t.userIds.owner,
) {
  const number = await issueRepo.nextIssueNumber(t.org.id, t.project.id);
  const base = issueInput(t.org.id, t.project.id, overrides);
  return issueRepo.insertIssue(
    { ...base, status: overrides.status ?? "backlog", description: overrides.description ?? null, labelIds },
    author,
    number,
  );
}

function list(extra: Record<string, unknown>) {
  return issueRepo.listIssues({ orgId: t.org.id, limit: 100, cursor: null, ...extra } as any);
}

describe("scratch: repo + service + codec", () => {
  it("1. unassigned narrows to unassigned issues only, total agrees", async () => {
    const assigned = await insert({ title: "assigned", assigneeId: t.userIds.member });
    const free = await insert({ title: "free", assigneeId: null });
    const page = await list({ assigneeId: null });
    expect(page.items.map((i) => i.id)).toContain(free.id);
    expect(page.items.map((i) => i.id)).not.toContain(assigned.id);
    expect(page.total).toBe(page.items.length);
    // Unfiltered assignee still shows everything.
    const all = await list({});
    expect(all.total).toBeGreaterThan(page.total);
  });

  it("3. labels are all-of, and the total counts the same rows", async () => {
    const l1 = await labelRepo.insertLabel({ orgId: t.org.id, name: "bug-a", color: "#ef4444", description: null });
    const l2 = await labelRepo.insertLabel({ orgId: t.org.id, name: "regression-a", color: "#22c55e", description: null });
    const onlyOne = await insert({ title: "only l1" }, [l1.id]);
    const both = await insert({ title: "both" }, [l1.id, l2.id]);
    await insert({ title: "only l2" }, [l2.id]);
    const page = await list({ labelIds: [l1.id, l2.id] });
    expect(page.items.map((i) => i.id)).toEqual([both.id]);
    expect(page.total).toBe(1);
    const one = await list({ labelIds: [l1.id] });
    expect(one.items.map((i) => i.id)).toEqual(expect.arrayContaining([onlyOne.id, both.id]));
    expect(one.total).toBe(2);
  });

  it("4. due_before: a calendar date includes its whole UTC day; a timestamp is strict", async () => {
    const early = await insert({ title: "due 8th late", dueAt: "2026-10-08T23:59:59.999Z" });
    const during = await insert({ title: "due 9th 18:00", dueAt: "2026-10-09T18:00:00Z" });
    const midnightNext = await insert({ title: "due 10th 00:00", dueAt: "2026-10-10T00:00:00Z" });
    const dateFilter = await list({ dueBefore: "2026-10-09" as CalendarDate });
    const ids = dateFilter.items.map((i) => i.id);
    expect(ids).toEqual(expect.arrayContaining([early.id, during.id]));
    expect(ids).not.toContain(midnightNext.id);
    expect(dateFilter.total).toBe(dateFilter.items.length);

    const ts = await list({ dueBefore: toIsoTimestamp("2026-10-09T18:00:00Z") });
    const tsIds = ts.items.map((i) => i.id);
    expect(tsIds).toContain(early.id);
    expect(tsIds).not.toContain(during.id);
    expect(tsIds).not.toContain(midnightNext.id);
  });

  it("5. status=open equals its four members, in the repo and in the codec", async () => {
    const viaGroup = await list({ status: ["open"] });
    const viaNames = await list({ status: ["backlog", "todo", "in_progress", "in_review"] });
    expect(viaGroup.items.map((i) => i.id).sort()).toEqual(viaNames.items.map((i) => i.id).sort());
    expect(viaGroup.total).toBe(viaNames.total);

    const parsed = parseIssueFilterParams(new URLSearchParams("status=open"));
    expect(parsed.status).toEqual(["backlog", "todo", "in_progress", "in_review"]);
    expect(issueFilterToParams(parsed).status).toBe("open");
    expect(issueFilterSchema.safeParse({ orgId: t.org.id, status: ["open", "closed"] }).success).toBe(true);
    expect(issueFilterSchema.safeParse({ orgId: t.org.id, status: ["nonsense"] }).success).toBe(false);
    expect(exportIssuesSchema.safeParse({ orgId: t.org.id, status: ["open"] }).success).toBe(true);
    expect(exportIssuesSchema.safeParse({ orgId: t.org.id, status: ["open"], format: "json" }).data).toMatchObject({ status: ["open"] });
  });

  it("6. archived=only lists archived issues and nothing else", async () => {
    const gone = await insert({ title: "to archive" });
    const live = await insert({ title: "still live" });
    await issueRepo.archiveIssue(t.org.id, gone.id);
    const only = await list({ archivedOnly: true });
    expect(only.items.map((i) => i.id)).toEqual([gone.id]);
    expect(only.total).toBe(1);
    const withArchived = await list({ includeArchived: true });
    expect(withArchived.items.map((i) => i.id)).toEqual(expect.arrayContaining([gone.id, live.id]));
    const parsed = parseIssueFilterParams(new URLSearchParams("archived=only"));
    expect(parsed).toEqual({ archivedOnly: true });
    expect(issueFilterToParams(parsed)).toEqual({ archived: "only" });
  });

  it("2. assignee=me is resolved by the service against the acting user, the same as a page", async () => {
    const mine = await insert({ title: "for member", assigneeId: t.userIds.member, status: "todo" });
    const parsed = issueFilterSchema.parse({ orgId: t.org.id, ...parseIssueFilterParams(new URLSearchParams("assignee=me")), limit: 100 });
    const page = await issueService.listIssues(t.actors.member, parsed);
    expect(page.items.map((i) => i.id)).toContain(mine.id);
    expect(page.items.every((i) => i.assigneeId === t.userIds.member)).toBe(true);
    expect(page.total).toBe(page.items.length);
    const author = await issueService.listIssues(t.actors.member, issueFilterSchema.parse({ orgId: t.org.id, authorId: "me", limit: 100 }));
    expect(author.items.every((i) => i.authorId === t.userIds.member)).toBe(true);
  });

  it("q is a literal substring: % and _ are not wildcards", async () => {
    const pct = await insert({ title: "100% shipped" });
    await insert({ title: "100 shipped" });
    const page = await list({ query: "100%" });
    expect(page.items.map((i) => i.id)).toEqual([pct.id]);
    expect(page.total).toBe(1);
  });

  it("codec round-trips the new vocabulary", () => {
    const filter = parseIssueFilterParams(
      new URLSearchParams("status=closed&assignee=none&due_before=2026-10-09&archived=1&label=a,b"),
    );
    expect(filter.status).toEqual(["done", "canceled"]);
    expect(filter.assigneeId).toBeNull();
    expect(filter.dueBefore).toBe("2026-10-09");
    expect(filter.includeArchived).toBe(true);
    expect(issueFilterSchema.safeParse({ orgId: t.org.id, ...filter }).success).toBe(true);
    expect(parseIssueFilterParams(new URLSearchParams("due_before=2026-02-30")).dueBefore).toBeUndefined();
    expect(parseIssueFilterParams(new URLSearchParams("due_before=2026-10-09T10:00:00%2B09:00")).dueBefore).toBe("2026-10-09T01:00:00.000Z");
    expect(issueFilterSchema.safeParse({ orgId: t.org.id, dueBefore: "2026-02-30" }).success).toBe(false);
  });

  it("sidebar href keeps its query", () => {
    expect(withSearchParams(orgPath("acme", "issues"), { assignee: "me" })).toBe("/acme/issues?assignee=me");
  });
});

