export const UNASSIGNED_TOKEN = "none";

export interface ReadableParams {
  get(name: string): string | null;
}

function splitList(raw: string | null): readonly string[] {
  if (raw === null || raw.length === 0) return [];
  return raw
    .split(",")
    .map((part) => part.trim())
    .filter((part) => part.length > 0);
}

/** An absent or empty parameter both mean "do not filter on it". */
function nonEmpty(raw: string | null): string | null {
  return raw === null || raw.length === 0 ? null : raw;
}

function isStatusFilterValue(
  value: string,
): value is IssueStatus | IssueStatusGroup {
  return issueStatusFilterSchema.safeParse(value).success;
}

/** Keeps a `due_before` the shared schema accepts; anything else is dropped. */
function parseDueBefore(
  raw: string | null,
): IsoTimestamp | CalendarDate | undefined {
  if (raw === null) return undefined;
  const parsed = dueBeforeSchema.safeParse(raw);
  return parsed.success ? parsed.data : undefined;
}

export function parseIssueFilterParams(params: ReadableParams): IssueFilter {
  // Groups expand here, so everything downstream sees concrete statuses.
  const statuses = expandIssueStatuses(
    splitList(params.get("status")).filter(isStatusFilterValue),
  );
  const priorities = splitList(params.get("priority")).filter(
    (value): value is IssuePriority =>
      ISSUE_PRIORITIES.includes(value as IssuePriority),
  );
  const labelIds = splitList(params.get("label")) as readonly LabelId[];
  const project = nonEmpty(params.get("project"));
  const assignee = nonEmpty(params.get("assignee"));
  const author = nonEmpty(params.get("author"));
  const query = nonEmpty(params.get("q"));
  const dueBefore = parseDueBefore(nonEmpty(params.get("due_before")));
  const archived = params.get("archived");

  const filter: IssueFilter = {
    ...(project !== null ? { projectId: project as ProjectId } : {}),
    ...(statuses.length > 0 ? { status: statuses } : {}),
    ...(priorities.length > 0 ? { priority: priorities } : {}),
    ...(assignee !== null
      ? {
          assigneeId:
            assignee === UNASSIGNED_TOKEN
              ? null
              : assignee === ME_FILTER_TOKEN
                ? ME_FILTER_TOKEN
                : (assignee as UserId),
        }
      : {}),
    ...(author !== null
      ? {
          authorId:
            author === ME_FILTER_TOKEN ? ME_FILTER_TOKEN : (author as UserId),
        }
      : {}),
    ...(labelIds.length > 0 ? { labelIds } : {}),
    ...(query !== null ? { query } : {}),
    ...(dueBefore !== undefined ? { dueBefore } : {}),
    ...(archived === "only" ? { archivedOnly: true } : {}),
